async function runOrderWorker(channel: amqp.Channel): Promise<void> {
  await channel.assertExchange(EXCHANGES.DIRECT, ExchangeKind.Direct, { durable: true })
  await channel.assertQueue(QUEUES.ORDERS_PROCESS, { durable: true })
  await channel.bindQueue(QUEUES.ORDERS_PROCESS, EXCHANGES.DIRECT, ORDERS_ROUTING_KEY)
  await channel.prefetch(1)
  await channel.consume(QUEUES.ORDERS_PROCESS, async (msg) => {
    if (!msg) return
    // Ack right away — the broker now considers this message DONE.
    channel.ack(msg)
    const order = JSON.parse(msg.content.toString())
    await fulfillmentService.fulfill(order) // throws, or the process can crash, mid-flight
  })
}
